function active$&Identity;Filter$(f) {
	var g = f.grid, w = g.get_element().parentForm, d2;
	if (w._controller == 'FADisposal') d2 = w.getItemValue('ngay_giam');
		else if (w._controller == 'DefinitionOfPeriodicAllocationEntries') d2 = w.getItemValue('ngay_bd');
						else d2 = w.getItemValue('ngay_ct');
	f.setItemValues('ngay_ct2', [d2]);

	if (w._controller == 'DefinitionOfPeriodicAllocationEntries') f.setItemControlBehavior('tk_ts', '', '', null); f.setItemControlBehavior('tk', '', '', null);
}
function close$&Identity;Filter$(f) {}
function on$&Identity;Filter$Retrieve$QueryComplete(f, h, l) {
	var g = f.grid;
	g._filter$Fields = l;
	set$&Identity;Filter$FormScript(g, h);
}
function set$&Identity;Filter$FormScript(g, h) { g._formScript = 'show$&Identity;Filter$QueryComplete(this,\'' + (h ? h : '') + '\')'; }
function show$&Identity;Filter$QueryComplete(g, h) {
	g.showForm(h);
	g._memvars = [];
}




